<template>
  <div class="app-container gift-management">
    <div class="page-title"><div><h2>赠品管理</h2><p>按店铺和付款时间匹配活动；策略组按优先级执行，组内策略可顺序叠加。</p></div><el-button v-hasPermi="['order:gift:config']" type="primary" icon="el-icon-plus" @click="edit()">新增策略组</el-button></div>
    <el-tabs v-model="tab" @tab-click="tabChanged"><el-tab-pane label="赠品策略组" name="groups"><el-alert title="优先级数字越小越先执行。组内未命中继续下一条；默认选中一个策略组后不再参加后续组。赠品不足时等待补货，不静默切换活动。" :closable="false" type="info" show-icon/>
      <el-table v-loading="loading" :data="groups" style="margin-top:18px" empty-text="暂无赠品策略组，新增后对后续新转单生效"><el-table-column prop="priority" label="优先级" width="90"/><el-table-column label="策略组 / 适用范围" min-width="270"><template slot-scope="s"><strong>{{ s.row.name }}</strong><div class="hint">{{ shopNames(s.row.policy.channels) }}</div><div class="hint">{{ s.row.policy.start_time }} 至 {{ s.row.policy.end_time }}</div></template></el-table-column><el-table-column label="串联执行" min-width="260"><template slot-scope="s"><div v-for="(r,i) in s.row.policy.rules" :key="r.key">{{ i+1 }}. {{ r.name }} · {{ types[r.type] }}<span class="hint">{{ r.stop?' 命中后结束本组':' 命中后继续' }}</span></div><el-tag size="mini" effect="plain">{{ s.row.policy.cross_group_stack?'允许继续后续策略组':'命中本组后组间互斥' }}</el-tag></template></el-table-column><el-table-column label="售后处理" min-width="240"><template slot-scope="s"><div>未发：取消 / 先截单后取消</div><div>已发：{{ s.row.policy.shipped_policy==='KEEP'?'允许保留，无需追退':'不再满足条件时安排退回' }}</div><div class="hint">退差价{{ s.row.policy.difference_affects_amount?'影响':'不影响' }}金额门槛 · {{ s.row.policy.allow_waive?'允许授权豁免':'不允许豁免' }}</div></template></el-table-column><el-table-column label="状态 / 版本" width="130"><template slot-scope="s"><el-tag :type="s.row.enabled?'success':'info'">{{ s.row.enabled?'已启用':'已停用' }}</el-tag><div class="hint">版本 {{ s.row.revision }}</div></template></el-table-column><el-table-column label="操作" width="95" fixed="right"><template slot-scope="s"><el-button v-hasPermi="['order:gift:config']" type="text" @click="edit(s.row)">编辑</el-button></template></el-table-column></el-table>
    </el-tab-pane><el-tab-pane label="赠送与售后记录" name="records"><el-form inline size="small" @submit.native.prevent="loadRecords"><el-form-item><el-input v-model="query.number" clearable placeholder="OMS 单号 / 平台单号"/></el-form-item><el-button type="primary" @click="query.pageNum=1;loadRecords()">查询</el-button></el-form><el-table v-loading="loading" :data="records"><el-table-column label="订单" min-width="320"><template slot-scope="s"><el-link type="primary" @click="open(s.row.order_id)">{{ s.row.order_sn }}</el-link><div class="hint">平台 {{ s.row.platform_tid }} · 店铺 {{ shopNames([s.row.channel_id]) }}</div></template></el-table-column><el-table-column label="原赠品" min-width="240"><template slot-scope="s"><div v-for="g in s.row.gifts" :key="g.sku_sn">{{ g.sku_sn }} × {{ g.quantity }}</div></template></el-table-column><el-table-column label="当前处理提示" min-width="270"><template slot-scope="s"><span :class="s.row.gift_block_reason?'warning':''">{{ s.row.gift_block_reason||s.row.last_error||'查看赠品详情了解发货及追退进度' }}</span></template></el-table-column><el-table-column prop="create_time" label="生成时间" width="180"/><el-table-column label="操作" width="110"><template slot-scope="s"><el-button type="text" @click="open(s.row.order_id)">处理赠品</el-button></template></el-table-column></el-table><pagination v-show="total>0" :total="total" :page.sync="query.pageNum" :limit="20" @pagination="loadRecords"/></el-tab-pane><el-tab-pane label="订单试算" name="preview"><el-alert title="仅用当前发布规则试算，不追加赠品、不占库存。已生成赠品的订单仍采用原策略快照。" :closable="false" type="info"/><el-form inline size="small" style="margin-top:18px" @submit.native.prevent="preview"><el-form-item label="业务订单"><el-input v-model="previewId" placeholder="输入 OMS 单号 / 平台单号"/></el-form-item><el-button type="primary" :loading="loading" @click="preview">试算当前规则</el-button></el-form><template v-if="calculation"><el-alert :title="`试算赠品：${(calculation.gifts||[]).map(g=>g.sku_sn+' × '+g.quantity).join('，')||'未命中赠品'}`" :closable="false" type="success"/><div v-for="g in calculation.trace" :key="g.group_id" class="trace"><strong>优先级 {{ g.priority }} · {{ g.name }}：{{ g.reason }}</strong><div v-for="r in g.rules" :key="r.key">{{ r.matched?'✓':'—' }} {{ r.name }}：{{ r.reason }} · 门槛口径 {{ r.basis_quantity }} 件 / ¥{{ r.basis_amount }}</div></div></template></el-tab-pane></el-tabs>
    <el-dialog :title="form.id?'编辑赠品策略组':'新增赠品策略组'" :visible.sync="editor" width="1100px" append-to-body :close-on-click-modal="false" top="4vh">
      <el-alert title="保存为新版本；仅后续新转单使用新规则。订单既有赠品和售后核对继续采用生成时的规则版本。" type="info" :closable="false"/>
      <el-form v-if="form.policy" label-width="135px" size="small" class="editor"><div class="two"><el-form-item label="策略组名称" required><el-input v-model="form.name" maxlength="100"/></el-form-item><el-form-item label="优先级" required><el-input-number v-model="form.priority" :min="1" :max="100000" :precision="0"/><span class="hint"> 1 最高，同优先级按创建顺序</span></el-form-item></div><el-form-item label="适用店铺" required><el-select v-model="form.policy.channels" multiple filterable style="width:100%"><el-option v-for="s in shops" :key="s.channel_id" :value="Number(s.channel_id)" :label="s.channel_name"/></el-select></el-form-item><el-form-item label="付款时间范围" required><el-date-picker v-model="period" type="datetimerange" value-format="yyyy-MM-dd HH:mm:ss" range-separator="至" start-placeholder="开始时间" end-placeholder="结束时间"/></el-form-item><el-form-item label="组间执行"><el-switch v-model="form.policy.cross_group_stack" active-text="命中本组后继续后续组" inactive-text="命中本组后不再参加后续组"/></el-form-item>
        <h3>组内策略 · 从上到下执行</h3><div v-for="(r,i) in form.policy.rules" :key="r.key" class="rule"><div class="rule-heading"><strong>第 {{ i+1 }} 条</strong><div><el-button :disabled="i===0" type="text" @click="move(i,-1)">上移</el-button><el-button :disabled="i===form.policy.rules.length-1" type="text" @click="move(i,1)">下移</el-button><el-button :disabled="form.policy.rules.length===1" type="text" @click="form.policy.rules.splice(i,1)">删除</el-button></div></div><div class="two"><el-form-item label="策略名称" required><el-input v-model="r.name" maxlength="100"/></el-form-item><el-form-item label="赠送方式"><el-select v-model="r.type" @change="typeChanged(r)"><el-option v-for="(label,key) in types" :key="key" :value="key" :label="label"/></el-select></el-form-item></div><el-form-item label="购买 SKU 范围"><el-select v-model="r.skus" multiple filterable allow-create default-first-option style="width:100%" placeholder="输入购买 SKU 编码后回车；满额策略留空表示全部正品"/></el-form-item><el-form-item v-if="r.type==='AMOUNT'" label="满额门槛" required><el-input-number v-model="r.amount" :min="0" :precision="2"/><span class="hint"> 元，商品实付金额，不含运费</span></el-form-item><el-form-item v-if="['PRODUCT','MULTIPLE'].includes(r.type)" label="购买数量门槛"><el-input-number v-model="r.minimum" :min="1" :precision="0"/><span class="hint"> 件；所选购买 SKU 数量合计</span></el-form-item><el-form-item v-if="r.type==='MULTIPLE'" label="单单倍赠上限"><el-input-number v-model="r.cap" :min="1" :max="100000" :precision="0"/><span class="hint"> 倍</span></el-form-item><template v-if="r.type==='TIER'"><el-alert title="按最高满足阶梯赠送；不累计各阶梯，门槛从小到大配置。" type="info" :closable="false"/><div v-for="(tier,t) in r.tiers" :key="t" class="tier"><span>购买满 </span><el-input-number v-model="tier.minimum" :min="1" :precision="0" size="small"/><span> 件，赠送：</span><div v-for="(gift,j) in tier.gifts" :key="j" class="gift-edit"><gift-sku-picker v-model="gift.sku_sn" @selected="gift.goods_name=$event.goodsName"/><el-input-number v-model="gift.quantity" :min="1" :precision="0" size="small"/><el-button v-if="tier.gifts.length>1" type="text" @click="tier.gifts.splice(j,1)">移除</el-button></div><el-button type="text" @click="tier.gifts.push(newGift())">添加阶梯赠品</el-button><el-button v-if="r.tiers.length>1" type="text" @click="r.tiers.splice(t,1)">删除阶梯</el-button></div><el-button type="text" @click="r.tiers.push({minimum:r.tiers[r.tiers.length-1].minimum+1,gifts:[newGift()]})">添加阶梯</el-button></template><template v-else><el-form-item label="赠品" required><div v-for="(gift,j) in r.gifts" :key="j" class="gift-edit"><gift-sku-picker v-model="gift.sku_sn" @selected="gift.goods_name=$event.goodsName"/><el-input-number v-model="gift.quantity" :min="1" :precision="0" size="small"/><span>件</span><el-button v-if="r.gifts.length>1" type="text" @click="r.gifts.splice(j,1)">移除</el-button></div><el-button type="text" @click="r.gifts.push(newGift())">添加赠品</el-button></el-form-item></template><el-form-item label="命中后"><el-radio-group v-model="r.stop"><el-radio :label="false">继续本组下一条策略</el-radio><el-radio :label="true">结束本组</el-radio></el-radio-group></el-form-item></div><el-button :disabled="form.policy.rules.length>=30" icon="el-icon-plus" @click="form.policy.rules.push(newRule())">添加串联策略</el-button>
        <h3>库存与售后处理</h3><el-form-item label="赠品库存不足"><el-tag type="warning">等待补货，暂缓自动履约</el-tag><span class="hint"> 规则命中不代表已经预占成功</span></el-form-item><el-form-item label="未发赠品失效">自动取消；已下发的先撤回，仓库确认后取消</el-form-item><el-form-item label="已发赠品失效"><el-radio-group v-model="form.policy.shipped_policy"><el-radio label="RETURN">安排赠品退回</el-radio><el-radio label="KEEP">允许保留，不追退</el-radio></el-radio-group></el-form-item><el-form-item label="退差价"><el-checkbox v-model="form.policy.difference_affects_amount">影响满额门槛</el-checkbox><span class="hint"> 补偿、运费退款默认不影响购买数量</span></el-form-item><el-form-item label="授权豁免"><el-checkbox v-model="form.policy.allow_waive">允许有权限人员填写凭证后豁免追退</el-checkbox></el-form-item><el-form-item label="启用状态"><el-switch v-model="form.enabled" :active-value="1" :inactive-value="0"/></el-form-item></el-form><span slot="footer"><el-button @click="editor=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存策略组</el-button></span>
    </el-dialog>
    <el-dialog title="订单赠品与售后处理" :visible.sync="detailVisible" width="95%" append-to-body top="3vh"><order-gifts v-if="detailVisible" :order-id="selectedOrder" @changed="loadRecords"/><span slot="footer"><el-button @click="detailVisible=false">关闭</el-button></span></el-dialog>
  </div>
</template>
<script>
import * as api from '@/api/order/gift'
import GiftSkuPicker from './GiftSkuPicker'
import OrderGifts from './OrderGifts'
const newGift=()=>({sku_sn:'',quantity:1,goods_name:''})
const newRule=()=>({key:`R${Date.now()}${Math.random().toString(36).slice(2,6)}`,name:'',type:'AMOUNT',amount:100,minimum:1,cap:100,skus:[],gifts:[newGift()],tiers:[{minimum:1,gifts:[newGift()]}],stop:false})
export default {name:'GiftManagement',components:{GiftSkuPicker,OrderGifts},data:()=>({tab:'groups',groups:[],shops:[],records:[],total:0,loading:false,saving:false,editor:false,form:{},period:[],query:{number:'',pageNum:1},previewId:'',calculation:null,types:{AMOUNT:'满额赠',PRODUCT:'指定商品赠',MULTIPLE:'买多赠多',TIER:'阶梯赠'},detailVisible:false,selectedOrder:null}),async created(){this.shops=(await api.giftCatalog()).data;await this.load();if(this.$route.query.orderId)this.open(this.$route.query.orderId)},methods:{newGift,newRule,typeChanged(r){if(r.type==='TIER'&&!(r.tiers||[]).length)this.$set(r,'tiers',[{minimum:1,gifts:[newGift()]}])},async load(){this.loading=true;try{this.groups=(await api.giftGroups()).data}finally{this.loading=false}},async loadRecords(){this.loading=true;try{const d=(await api.giftRecords(this.query)).data;this.records=d.rows;this.total=d.total}finally{this.loading=false}},tabChanged(){if(this.tab==='records')this.loadRecords()},shopNames(ids){return (ids||[]).map(id=>{const s=this.shops.find(s=>Number(s.channel_id)===Number(id));return s?s.channel_name:`店铺 ${id}`}).join('、')},edit(row){this.form=row?JSON.parse(JSON.stringify(row)):{name:'',priority:1,enabled:0,revision:0,policy:{channels:[],cross_group_stack:false,shipped_policy:'RETURN',difference_affects_amount:false,allow_waive:true,rules:[newRule()]}};this.period=row?[row.policy.start_time,row.policy.end_time]:[];this.editor=true},move(index,delta){const rules=this.form.policy.rules;const r=rules.splice(index,1)[0];rules.splice(index+delta,0,r)},async save(){if(!this.form.name.trim()||!this.period||this.period.length!==2||!this.form.policy.channels.length)return this.$message.warning('请填写名称、适用店铺和付款时间范围');for(const r of this.form.policy.rules){if(!r.name.trim())return this.$message.warning('请填写每条策略名称');const sets=r.type==='TIER'?r.tiers.map(t=>t.gifts):[r.gifts];if(!sets.length||sets.some(gifts=>!gifts.length||gifts.some(g=>!g.sku_sn)))return this.$message.warning('请选择每条策略或阶梯的赠品 SKU');if(r.type==='TIER')r.gifts=JSON.parse(JSON.stringify(r.tiers[0].gifts));}this.saving=true;try{await api.saveGiftGroup({...this.form,policy:{...this.form.policy,start_time:this.period[0],end_time:this.period[1]}});this.editor=false;this.$message.success('赠品策略组已保存，新转单按发布规则匹配');await this.load()}finally{this.saving=false}},open(id){this.selectedOrder=id;this.detailVisible=true},async preview(){if(!this.previewId.trim())return this.$message.warning('请输入 OMS 单号或平台单号');this.loading=true;try{this.calculation=(await api.giftPreviewNumber(this.previewId.trim())).data}finally{this.loading=false}}} }
</script>
<style scoped>.page-title,.rule-heading{display:flex;justify-content:space-between;align-items:center}.page-title h2{margin:0}.page-title p,.hint{font-size:12px;color:#8491a3;line-height:1.8}.two{display:grid;grid-template-columns:1fr 1fr}.editor{margin-top:20px}.rule,.trace{border:1px solid #dfe6ef;border-radius:8px;padding:18px;margin:14px 0}.rule-heading{margin-bottom:12px}.gift-edit{display:flex;align-items:center;gap:12px;margin-bottom:8px}.tier{margin:14px 0;padding:14px;background:#f5f8fc}.warning{color:#a76b13}.trace>div{padding:8px 0;font-size:13px}</style>
